{"type":"object","additionalProperties":false,"required":["testCode","expectedTests"],"properties":{"testCode":{"type":"string"},"expectedTests":{"type":"integer","const":3}}}"},{"role":"user","content":"{"goal":"[PR181 selected-inline form and COMPACT REVIEW and CODING acceptance] local Node repair: Add formatClockDuration(seconds) to src/localBrain/examples/duration.js and export it alongside unchanged formatDuration. Return HH:MM:SS with two-digit minimum hours and exactly two-digit minutes/seconds; hours do not wrap at 24. Accept only nonnegative safe integer numbers and throw RangeError for every other input. Preserve all existing formatDuration and orderBoxes behavior and every read-only source/test byte. Produce exactly three protected acceptance tests preserving the complete baseline assertions. For each named subject orderBoxes, formatDuration and the new formatClockDuration, include at least one actual assert comparison containing a direct selected-relative require(...).namedExport(...) invocation on that assertion line, as required by the host selected_inline_assert_v1 contract. Real arguments and exact expected values are required; comments, imports, titles and aliases alone do not satisfy this minimum form. Isolated candidate only; no adoption, merge, deployment, cloud, website, background learning, installation or external dispatch.","criteria":["One top-level acceptance test preserves the existing exact-decimal orderBoxes examples and validation assertions from the read-only examples.test.js, including at least one executable assert comparison containing a direct selected-relative require('../src/localBrain/examples/stock.js').orderBoxes(...) call; stock.js remains byte-identical.","One top-level acceptance test preserves every existing formatDuration valid and invalid assertion from the read-only examples.test.js, including MAX_SAFE_INTEGER, and its export, with at least one executable assert comparison directly invoking require('../src/localBrain/examples/duration.js').formatDuration(...).","One top-level acceptance test exercises the new exported formatClockDuration, including an executable assert comparison directly invoking require('../src/localBrain/examples/duration.js').formatClockDuration(...): 0=00:00:00; 9=00:00:09; 59=00:00:59; 60=00:01:00; 3599=00:59:59; 3600=01:00:00; 86399=23:59:59; 86400=24:00:00; 360000=100:00:00; MAX_SAFE_INTEGER=2501999792983:36:31. Reject -1, 1.5, NaN, Infinity, -Infinity, MAX_SAFE_INTEGER+1, strings, null, undefined, booleans, objects, arrays and bigint with RangeError. Do not coerce or wrap hours."],"editable":["src/localBrain/examples/duration.js"],"protectedTestPath":"acceptance/registered-task.test.cjs","files":{"src/localBrain/examples/duration.js":"'use strict'\nfunction formatDuration(seconds) {\n  if(!Number.isSafeInteger(seconds)||seconds<0)throw new RangeError('seconds')\n  return Math.floor(seconds/60)+'m '+(seconds%60)+'s'\n}\nmodule.exports={formatDuration}\n","src/localBrain/examples/stock.js":"'use strict'\n// Decimal quantities follow Number.toString()'s canonical decimal value. Box\n// counts are exact integers; an unrepresentable count is a failure, not Infinity.\nfunction decimal(value) {\n  const [mantissa, exponent='0']=String(value).split('e'),digits=mantissa.replace('.','')\n  return {n:BigInt(digits),scale:(mantissa.split('.')[1]?.length||0)-Number(exponent)}\n}\nfunction orderBoxes(current,par,packSize) {\n  if([current,par,packSize].some(v=>typeof v!=='number'||!Number.isFinite(v))||current<0||par<0||packSize<=0)throw new RangeError('finite nonnegative quantities and a finite positive pack are required')\n  if(current>=par)return 0\n  const parts=[current,par,packSize].map(decimal),scale=Math.max(0,...parts.map(p=>p.scale))\n  const [have,target,pack]=parts.map(p=>p.n*10n**BigInt(scale-p.scale))\n  const count=(target-have+pack-1n)/pack\n  if(count>BigInt(Number.MAX_SAFE_INTEGER))throw new RangeError('box count exceeds safe integer range')\n  return Number(count)\n}\nmodule.exports={orderBoxes}\n","src/localBrain/examples/examples.test.js":"'use strict'\nconst test=require('node:test'),assert=require('node:assert/strict'),{orderBoxes}=require('./stock'),{formatDuration}=require('./duration')\ntest('whole-box examples use exact decimal quantities and never coerce invalid inputs',()=>{\n assert.equal(orderBoxes(3,10,4),2);assert.equal(orderBoxes(0.1,0.4,0.1),3);assert.equal(orderBoxes(0,1.1,0.1),11);assert.equal(orderBoxes(1.01,1.04,0.01),3);assert.equal(orderBoxes(12,10,4),0)\n for(const v of [NaN,Infinity,-Infinity,'2',undefined,null,true,{},[]])for(let i=0;i<3;i++){const args=[1,3,1];args[i]=v;assert.throws(()=>orderBoxes(...args),RangeError)}\n assert.equal(orderBoxes(0,Number.MIN_VALUE,Number.MIN_VALUE),1);assert.equal(orderBoxes(0,Number.MAX_SAFE_INTEGER,1),Number.MAX_SAFE_INTEGER);assert.throws(()=>orderBoxes(0,Number.MAX_VALUE,Number.MIN_VALUE),RangeError)\n})\ntest('duration examples preserve safe-integer input validation and exact remainder values',()=>{\n for(const s of [0,59,60,119,120,3600,Number.MAX_SAFE_INTEGER]){const n=BigInt(s);assert.equal(formatDuration(s),(n/60n)+'m '+(n%60n)+'s')}\n for(const s of [Number.MAX_SAFE_INTEGER+1,-1,1.5,NaN,Infinity,'60',null,undefined,{},60n])assert.throws(()=>formatDuration(s),RangeError)\n})\n"},"draftContract":{"expectedTests":3,"criteria":[{"id":1,"text":"One top-level acceptance test preserves the existing exact-decimal orderBoxes examples and validation assertions from the read-only examples.test.js, including at least one executable assert comparison containing a direct selected-relative require('../src/localBrain/examples/stock.js').orderBoxes(...) call; stock.js remains byte-identical.","requiredSubjects":[{"file":"src/localBrain/examples/stock.js","symbol":"orderBoxes"}]},{"id":2,"text":"One top-level acceptance test preserves every existing formatDuration valid and invalid assertion from the read-only examples.test.js, including MAX_SAFE_INTEGER, and its export, with at least one executable assert comparison directly invoking require('../src/localBrain/examples/duration.js').formatDuration(...).","requiredSubjects":[{"file":"src/localBrain/examples/duration.js","symbol":"formatDuration"}]},{"id":3,"text":"One top-level acceptance test exercises the new exported formatClockDuration, including an executable assert comparison directly invoking require('../src/localBrain/examples/duration.js').formatClockDuration(...): 0=00:00:00; 9=00:00:09; 59=00:00:59; 60=00:01:00; 3599=00:59:59; 3600=01:00:00; 86399=23:59:59; 86400=24:00:00; 360000=100:00:00; MAX_SAFE_INTEGER=2501999792983:36:31. Reject -1, 1.5, NaN, Infinity, -Infinity, MAX_SAFE_INTEGER+1, strings, null, undefined, booleans, objects, arrays and bigint with RangeError. Do not coerce or wrap hours.","requiredSubjects":[]}],"assertionForm":{"version":"selected_inline_assert_v1","subjects":[{"file":"src/localBrain/examples/stock.js","symbol":"orderBoxes","callee":"require(\"../src/localBrain/examples/stock.js\").orderBoxes"},{"file":"src/localBrain/examples/duration.js","symbol":"formatDuration","callee":"require(\"../src/localBrain/examples/duration.js\").formatDuration"}],"includeNewNamedSubjects":true},"baselineRole":"unchanged_reference_expected_to_fail","testsExecuted":false}}"}]}

